import csv
import json
from flask import Flask, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

def load_readings():
    readings = []
    with open("uploads/sensor_readings.csv", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            readings.append({
                "timestamp": row["timestamp"],
                "sensor": row["sensor"],
                "temperature_c": float(row["temperature_c"])
            })
    return readings

@app.route("/api/readings")
def api_readings():
    return jsonify(load_readings())

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=3000)

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    port: 8000,
    host: '0.0.0.0',
    proxy: {
      '/api': {
        target: 'http://localhost:3000',
        changeOrigin: true
      }
    }
  }
})

import { useState, useEffect } from 'react'
import './App.css'

function App() {
  const [readings, setReadings] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    fetch('/api/readings')
      .then(res => {
        if (!res.ok) throw new Error('Failed to fetch readings')
        return res.json()
      })
      .then(data => {
        setReadings(data)
        setLoading(false)
      })
      .catch(err => {
        setError(err.message)
        setLoading(false)
      })
  }, [])

  // Compute summary stats
  const count = readings.length
  const temps = readings.map(r => r.temperature_c)
  const minTemp = temps.length ? Math.min(...temps) : null
  const maxTemp = temps.length ? Math.max(...temps) : null
  const avgTemp = temps.length ? (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1) : null

  return (
    <div className="app">
      <h1>🌡️ Sensor Dashboard</h1>

      {/* Summary Cards */}
      <div className="summary-row">
        <div className="card">
          <span className="card-label">Total Readings</span>
          <span className="card-value">{loading ? '...' : count}</span>
        </div>
        <div className="card">
          <span className="card-label">Min Temp (°C)</span>
          <span className="card-value">{loading ? '...' : minTemp}</span>
        </div>
        <div className="card">
          <span className="card-label">Max Temp (°C)</span>
          <span className="card-value">{loading ? '...' : maxTemp}</span>
        </div>
        <div className="card">
          <span className="card-label">Avg Temp (°C)</span>
          <span className="card-value">{loading ? '...' : avgTemp}</span>
        </div>
      </div>

      {/* Table */}
      <div className="table-wrap">
        <h2>Readings</h2>
        {error && <p className="error">{error}</p>}
        {loading && <p>Loading readings…</p>}
        {!loading && !error && (
          <table>
            <thead>
              <tr>
                <th>Timestamp</th>
                <th>Sensor</th>
                <th>Temperature (°C)</th>
              </tr>
            </thead>
            <tbody>
              {readings.map((r, i) => (
                <tr key={i}>
                  <td>{r.timestamp}</td>
                  <td>{r.sensor}</td>
                  <td>{r.temperature_c}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  )
}

export default App

#root {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem;
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #1a1a2e;
}

.dashboard {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

h1 {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 0.5rem;
  color: #16213e;
}

/* Summary Cards */
.summary-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

.card {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  border-radius: 12px;
  padding: 1.5rem;
  color: white;
  text-align: center;
  box-shadow: 0 4px 15px rgba(102, 126, 234, 0.3);
  transition: transform 0.2s;
}

.card:hover {
  transform: translateY(-2px);
}

.card:nth-child(2) {
  background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
  box-shadow: 0 4px 15px rgba(245, 87, 108, 0.3);
}

.card:nth-child(3) {
  background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
  box-shadow: 0 4px 15px rgba(79, 172, 254, 0.3);
}

.card-label {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  opacity: 0.9;
  margin-bottom: 0.5rem;
}

.card-value {
  font-size: 2rem;
  font-weight: 700;
}

/* Table */
.table-container {
  background: white;
  border-radius: 12px;
  box-shadow: 0 2px 20px rgba(0, 0, 0, 0.08);
  overflow: hidden;
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead {
  background: #16213e;
  color: white;
}

th {
  padding: 1rem;
  text-align: left;
  font-weight: 600;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #eee;
  font-size: 0.95rem;
}

tbody tr:hover {
  background: #f8f9ff;
}

tbody tr:last-child td {
  border-bottom: none;
}

.sensor-tag {
  display: inline-block;
  background: #e8eaf6;
  color: #3949ab;
  padding: 0.2rem 0.6rem;
  border-radius: 6px;
  font-size: 0.85rem;
  font-weight: 500;
}

.temp-value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.temp-high {
  color: #e53935;
}

.temp-mid {
  color: #fb8c00;
}

.temp-low {
  color: #43a047;
}

/* Loading & Error */
.loading,
.error {
  text-align: center;
  padding: 3rem;
  font-size: 1.2rem;
  color: #666;
}

.error {
  color: #e53935;
}

/* Responsive */
@media (max-width: 600px) {
  .summary-cards {
    grid-template-columns: 1fr;
  }

  th, td {
    padding: 0.5rem;
    font-size: 0.85rem;
  }
}

:root {
  font-family: system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  color: #213547;
  background-color: #f8fafc;
}

body {
  margin: 0;
}
